@Override public byte[] evaluateResponse(final byte[] response) throws SaslException {
  byte[] challenge;
  try {
    switch (state) {
      case INITIAL:    
        challenge=generateServerFirstMessage(response);
        state=State.IN_PROGRESS;
        break;
      case IN_PROGRESS:
        challenge=generateServerFinalMessage(response);
        state=State.COMPLETE;
        break;
      case COMPLETE:
        if (response == null || response.length == 0) {
          challenge=new byte[0];
          break;
        }
      default:
        throw new SaslException("No response expected in state " + state);
    }
  } catch (IndexOutOfBoundsException | IllegalFormatException e) {
    throw new SaslException(e.getMessage(), e);
  }
  return challenge;
}
